const BY_ID = new Map(DIARY_QUOTES.map((q) => [q.id, q]));
export const DIARY_SCHOOLS = Object.freeze([...new Set(DIARY_QUOTES.map((q) => q.school))].sort((a, b) => a.localeCompare(b, 'it')));
export const DIARY_THEMES = Object.freeze([...new Set(DIARY_QUOTES.map((q) => q.theme))].sort((a, b) => a.localeCompare(b, 'it')));
export const DIARY_AUTHORS = Object.freeze([...new Map(DIARY_QUOTES.map((q) => [q.authorId, Object.freeze({ id: q.authorId, name: q.author, era: q.era, school: q.school })])).values()]);

// Alternate eras, then authors within each era, before taking another passage.
function interleave(groups) {
  const result = [];
  for (let i = 0; groups.some((g) => i < g.length); i++) for (const group of groups) if (group[i]) result.push(group[i]);
  return result;
}
const SEQUENCE = interleave(Object.keys(DIARY_ERAS).map((era) => interleave(DIARY_AUTHORS.filter((a) => a.era === era).map((a) => DIARY_QUOTES.filter((q) => q.authorId === a.id)))));
export const quoteForPage = (page) => BY_ID.get(page?.quoteId) || null;
export const quoteText = (quote) => quote.kind === 'thought' ? quote.text : `“${quote.text}”`;
export const quoteKindLabel = (quote) => quote.kind === 'thought' ? 'Riflessione dal testo' : 'Traduzione redazionale';

// Reserve valid pins first, repair collisions, then allocate unused passages.
// No modulo cycling: after exhaustion a page has no quote instead of a duplicate.
// Pure; loading legacy pages never writes to the archive automatically.
export function assignDiaryQuotes(pages) {
  const assigned = new Map(), used = new Set();
  for (const page of pages) {
    const quote = quoteForPage(page);
    if (quote && !used.has(quote.id)) { assigned.set(page.id, quote.id); used.add(quote.id); }
  }
  let cursor = 0;
  const pending = [...pages].filter((p) => !assigned.has(p.id)).sort((a, b) => a.id.localeCompare(b.id));
  for (const page of pending) {
    while (cursor < SEQUENCE.length && used.has(SEQUENCE[cursor].id)) cursor++;
    if (cursor < SEQUENCE.length) { const id = SEQUENCE[cursor++].id; assigned.set(page.id, id); used.add(id); }
  }
  return pages.map((p) => {
    const quoteId = assigned.get(p.id) || null;
    return p.quoteId === quoteId ? p : { ...p, quoteId };
  });
}
export function selectDiaryQuote(pages, pageId, quoteId) {
  if (!pages.some((p) => p.id === pageId)) throw new Error('La pagina non è disponibile.');
  if (!BY_ID.has(quoteId)) throw new Error('Questo pensiero non è disponibile.');
  if (pages.some((p) => p.id !== pageId && p.quoteId === quoteId)) throw new Error('Questo pensiero accompagna già un’altra pagina. Scegline uno diverso.');
  return pages.map((p) => p.id === pageId ? { ...p, quoteId } : p);
}
const normalize = (text) => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('it');
export function filterDiaryQuotes({ era = '', school = '', theme = '', query = '' } = {}) {
  const words = normalize(query.trim()).split(/\s+/).filter(Boolean);
  return DIARY_QUOTES.filter((q) => (!era || q.era === era) && (!school || q.school === school) && (!theme || q.theme === theme) && words.every((word) => normalize(`${q.author} ${q.text} ${q.work} ${q.school} ${q.theme}`).includes(word)));
}
